(window.GO_WEB=window.GO_WEB||{})["fr"]={"felles":{"_sprak":"Langue","nav_browse":"Voir les jeux","nav_submit":"Proposer un jeu","nav_privacy":"Confidentialité","hjem":"Accueil"},"index":{"_title":"GiveOwl – Jeux-concours et tirages au sort au même endroit","_desc":"GiveOwl rassemble des jeux-concours et tirages au sort auxquels participer, et des calendriers de l’Avent en ligne en saison. Gratuit, sans compte, et vous participez toujours chez l’organisateur.","h1":"Tous les jeux-concours qui valent le coup, <em>au même endroit.</em>","lead":"GiveOwl rassemble des jeux-concours et tirages au sort auxquels participer, et des calendriers de l’Avent en ligne en saison. Filtrez par pays, écartez ceux qui exigent un achat et participez chez l’organisateur.","cta":"Voir les jeux-concours","snart":"Bientôt sur","senere":"Plus tard sur l’","h2_hva":"Ce que fait GiveOwl","under_hva":"Une liste claire au lieu de cent onglets.","k1_t":"Adapté à votre pays","k1":"GiveOwl choisit votre pays d’après votre appareil : États-Unis, Royaume-Uni, Canada, pays nordiques et bien d’autres à venir. Modifiable à tout moment.","k2_t":"Sans obligation d’achat","k2":"Le filtre est activé par défaut : vous ne voyez que des jeux gratuits. Date limite, lots et modalités en un coup d’œil.","k3_t":"Calendriers de l’Avent en saison","k3":"En novembre et décembre, les calendriers de l’Avent en ligne ont leur propre onglet, avec les cases du jour de vos favoris.","trygg_t":"Nous ne faisons que des liens. Vous participez chez l’organisateur.","trygg":"GiveOwl ne collecte jamais vos participations, ne demande aucun compte et ne vous facture rien. Lisez toujours le règlement officiel sur le site de l’organisateur avant de participer.","h2_arr":"Vous organisez un jeu-concours ?","under_arr":"Parlez-nous-en. Le référencement est gratuit.","cta_arr":"Proposer un jeu","fot":"GiveOwl n’est pas affilié aux organisateurs présentés. © 2026 HENDTAS, Norvège.","fot_aff":"Les offres marquées « Pub » ou « Sponsorisé » sont des emplacements payants ou des liens d’affiliation. Si vous participez ou achetez via ces liens, nous pouvons toucher une commission, sans frais pour vous. Cela ne décide jamais des jeux que nous listons. <a href=\"/privacy/#ads\">En savoir plus</a>"},"submit":{"_title":"Proposer un jeu-concours – GiveOwl","h1":"Proposer un jeu-concours","lead":"Vous organisez un jeu-concours, un tirage au sort ou un calendrier de l’Avent en ligne ? Parlez-nous-en. Le référencement est gratuit et nous vérifions chaque proposition avant publication.","f_arr":"Organisateur / marque *","f_tittel":"Nom du jeu *","f_premie":"Lot(s) *","p_premie":"ex. carte cadeau de 500 €, 3 gagnants","f_type":"Type","o_konk":"Jeu-concours / tirage au sort","o_jul":"Calendrier de l’Avent en ligne","f_land":"Ouvert aux résidents de *","o_int":"Monde entier","f_start":"Date de début","f_slutt":"Date de fin / date limite *","f_url":"Lien vers le jeu ou le règlement officiel (votre propre site) *","f_delta":"Comment participer","p_delta":"ex. Remplir le formulaire une fois par jour. 18 ans et plus.","f_kjop":"Sans obligation d’achat (il existe un moyen gratuit de participer)","f_epost":"Votre e-mail (pour vous répondre) *","f_ok":"Je suis l’organisateur ou j’ai le droit de proposer ce jeu, et les informations sont exactes.","send":"Envoyer par e-mail","kopier":"Copier les informations","ft_t":"Mettez votre jeu en avant","ft_lead":"Envie de plus de participants ? Les annonces sponsorisées apparaissent en haut de la liste (deux maximum à la fois) et sont toujours clairement marquées « Sponsorisé ». Les annonces normales restent gratuites.","ft_1":"Un emplacement en haut de liste dans les pays de votre choix","ft_2":"Clairement marqué « Sponsorisé », conformément aux règles publicitaires","ft_3":"Les mêmes règles de qualité que toutes les annonces : vrai organisateur, règlement officiel, aucune participation payante déguisée","ft_pris_t":"Tarifs :","ft_pris":"à venir. Contactez-nous pour les prix et les disponibilités.","ft_cta":"Écrire à info@hendtas.com","merk":"Cette page n’enregistre rien. « Envoyer par e-mail » ouvre votre propre messagerie avec les informations déjà remplies. Consultez notre <a href=\"/privacy/\">politique de confidentialité</a>.","mangler":"Veuillez remplir les champs obligatoires (*).","kopiert":"Copié. Collez-le dans un e-mail à ","aapner":"Ouverture de votre messagerie…"},"privacy":{"_title":"GiveOwl – Politique de confidentialité","_html":"<div class=\"card binding\"><b>Cette traduction est fournie pour votre confort. Seule la version anglaise fait foi ; en cas de divergence, l’anglais prévaut.</b> <a href=\"#en\">English</a></div>\n<h1>Politique de confidentialité de GiveOwl</h1>\n<p class=\"meta\">Dernière mise à jour : 17 octobre 2026 · S’applique à l’application Android « GiveOwl » (nom de package <code>com.hendtas.giveowl</code>) et au site giveowl.com</p>\n<div class=\"card\"><b>En bref :</b> GiveOwl est un répertoire de jeux-concours, tirages au sort et calendriers de l’Avent en ligne. Il n’y a ni compte utilisateur, ni publicité, ni achat, ni outil d’analyse. Vos favoris et réglages sont enregistrés uniquement sur votre appareil. Quand vous participez à un jeu, vous le faites sur le site de l’organisateur. Ce que vous y envoyez va à l’organisateur, pas à nous. Nous ne vendons ni ne partageons de données personnelles.</div>\n<h2>1. Qui est responsable ?</h2>\n<p>Le responsable du traitement est HENDTAS, Norvège. E-mail : <a href=\"mailto:info@hendtas.com\">info@hendtas.com</a>.</p>\n<h2>2. Ce qui est enregistré sur votre appareil</h2>\n<p>Les éléments suivants sont enregistrés localement dans l’application (ou dans votre navigateur sur giveowl.com). Nous n’y avons pas accès et ils ne nous sont pas envoyés :</p>\n<ul><li>les jeux et calendriers que vous avez ajoutés en favoris ;</li><li>les jeux auxquels vous avez indiqué avoir participé (« Mes participations » et « Aujourd’hui ») et les jours concernés, pour les séries et la grille du calendrier de l’Avent ;</li><li>vos réglages : langue, pays, filtres et tri (par exemple « Sans obligation d’achat ») et vos réglages de rappels ;</li><li>une copie de la dernière liste téléchargée par l’application, pour qu’elle fonctionne hors ligne.</li></ul>\n<p>Votre langue et votre pays sont choisis d’après les réglages de votre appareil à la première ouverture de GiveOwl. Cela se passe sur votre appareil ; nous n’utilisons pas votre position. Si la sauvegarde automatique d’Android est activée, elle peut inclure les données de l’application dans la sauvegarde de votre compte Google. Vous pouvez supprimer toutes les données en désinstallant l’application, via « Vider le stockage » dans les réglages Android ou en effaçant les données du site dans votre navigateur.</p>\n<p>GiveOwl n’a ni connexion, ni publicité, ni achat intégré, ni outil d’analyse, ni cookie de suivi, ni rapport de plantage. L’application ne demande pas l’accès à votre position, vos contacts, votre appareil photo, votre micro ou vos fichiers.</p>\n<h3>Rappels</h3>\n<p>Si vous activez les rappels, l’application demande à Android l’autorisation d’afficher des notifications. Les rappels (par exemple la veille de la clôture d’un jeu favori) sont programmés localement sur votre appareil par Android. Aucune donnée de rappel ne nous est envoyée ni à un service de notifications push, et vous pouvez désactiver les rappels à tout moment dans l’application ou dans les réglages Android.</p>\n<h3>Partage</h3>\n<p>Quand vous touchez « Partager », le menu de partage d’Android s’ouvre avec un lien vers la fiche sur giveowl.com. Vous choisissez l’application avec laquelle partager, et c’est sa politique de confidentialité qui s’applique. Rien ne nous est envoyé.</p>\n<h3>Noter l'application</h3>\n<p>Après un certain temps d'utilisation, l'application Android peut demander à Google Play d'afficher la fenêtre de notation de Google (au maximum une fois tous les 90 jours). Si vous laissez une note ou un avis, il est envoyé à Google Play et traité selon les conditions et la politique de confidentialité de Google, comme un avis rédigé dans le Play Store. GiveOwl ne reçoit aucune information de cette fenêtre, pas même si vous avez noté l'application.</p>\n<h2>3. Mise à jour de la liste</h2>\n<p>Pour afficher de nouveaux jeux, l’application télécharge une liste à jour depuis <code>https://giveowl.com/data.json</code>. La requête ne contient aucune information sur vous, mais comme pour toute requête web, le serveur voit votre adresse IP et des informations techniques comme le type d’appareil ou de navigateur. Le service qui héberge le site et la liste, GitHub Pages (GitHub, Inc.), peut conserver ces données dans des journaux techniques de courte durée selon ses propres règles. Nous n’utilisons pas ces données pour vous identifier.</p>\n<p>Si vous activez les notifications « Nouveautés » dans l'application Android, Android télécharge la même liste en arrière-plan environ deux fois par jour, uniquement lorsque vous êtes connecté. L'application la compare sur votre appareil avec les offres que vous avez déjà vues et affiche une seule notification s'il y a du nouveau. La liste des offres vues reste sur votre appareil, et la requête est la même que ci-dessus : elle ne contient aucune information sur vous. Vous pouvez désactiver cette fonction à tout moment dans les réglages de l'application.</p>\n<h2>4. Proposer un jeu</h2>\n<p>La page « Proposer un jeu » de giveowl.com n’enregistre rien. Elle prépare un e-mail dans votre propre messagerie. Si vous l’envoyez, nous recevons les informations saisies et votre adresse e-mail, que nous utilisons uniquement pour examiner la proposition et vous répondre. Nous supprimons l’e-mail lorsqu’il n’est plus utile, généralement sous 12 mois.</p>\n<h2>5. Liens vers les organisateurs</h2>\n<p>GiveOwl ne fait que renvoyer vers d’autres sites. Quand vous touchez « Participer chez l’organisateur », le site de l’organisateur s’ouvre dans votre navigateur et son règlement officiel ainsi que sa politique de confidentialité s’appliquent. Nous ne sommes pas responsables des jeux, des lots ni du traitement des données par les organisateurs. Les annonces payantes sont marquées « Sponsorisé » et les liens d’affiliation « Pub » (voir section 5a).</p>\n<h2 id=\"tr-ads\">5a. Annonces sponsorisées, liens d’affiliation et publicité</h2>\n<p>GiveOwl peut afficher des annonces sponsorisées (marquées « Sponsorisé ») et des liens d’affiliation (marqués « Pub »). Avec un lien d’affiliation, l’organisateur ou un réseau d’affiliation peut nous verser une commission si vous participez ou achetez après avoir suivi le lien. Cela ne vous coûte rien de plus. Le paiement ne décide jamais des jeux que nous listons ni de la façon dont nous les décrivons, et nous ne listons que des jeux conformes à nos règles de qualité.</p>\n<p>Quand vous ouvrez un tel lien, il s’ouvre dans votre navigateur, et le réseau d’affiliation ou l’organisateur peut utiliser des cookies ou des technologies similaires sur son propre site pour enregistrer que vous venez de GiveOwl. Cela relève de leur politique de confidentialité, pas de l’application GiveOwl. L’application elle-même ne vous suit pas.</p>\n<p>GiveOwl n’affiche pas de publicité dans l’application aujourd’hui. Si nous en ajoutons plus tard, nous mettrons d’abord à jour cette politique et les informations de sécurité des données de l’application.</p>\n<h2>6. Enfants</h2>\n<p>GiveOwl s’adresse aux adultes de 18 ans et plus, car la plupart des jeux-concours n’acceptent que les participants majeurs (certains exigent 21 ans), comme l’indique le règlement de l’organisateur. GiveOwl ne s’adresse pas aux enfants. Nous ne collectons pas sciemment de données personnelles d’enfants, et l’application ne collecte de données personnelles de personne.</p>\n<h2>7. Vos droits</h2>\n<p>Selon votre lieu de résidence (par exemple le RGPD dans l’EEE et au Royaume-Uni, ou les lois des États américains comme le CCPA/CPRA), vous pouvez disposer de droits d’accès, de rectification, d’effacement ou de limitation du traitement de vos données personnelles, de portabilité, d’opposition et du droit de refuser la vente ou le partage de vos données. Nous ne vendons ni ne partageons de données personnelles et n’avons pas de comptes utilisateurs, nous ne pouvons donc généralement relier aucune donnée à vous. Écrivez-nous à <a href=\"mailto:info@hendtas.com\">info@hendtas.com</a> et nous vous aiderons. Vous ne serez pas discriminé pour avoir exercé vos droits. Dans l’EEE, vous pouvez aussi porter plainte auprès de l’autorité norvégienne de protection des données (Datatilsynet, <a href=\"https://www.datatilsynet.no/en/\">datatilsynet.no</a>) ou de votre autorité locale (en France, la CNIL).</p>\n<h2>8. Modifications</h2>\n<p>Nous mettons à jour cette politique lorsque GiveOwl évolue, par exemple lors de l’ajout de fonctionnalités ou de prestataires. La date en haut indique la version en vigueur.</p>\n<h2>9. Contact</h2>\n<p>HENDTAS · Norvège · <a href=\"mailto:info@hendtas.com\">info@hendtas.com</a></p>\n"},"seo":{"g_h1":"Jeux-concours en {land}","g_title":"Jeux-concours et tirages au sort en {land} ({m}) – GiveOwl","g_desc":"{n} jeux-concours ouverts aux résidents ({land}), vérifiés le {d}. Date limite, lots et modalités de participation chez l’organisateur.","a_h1":"Calendriers de l’Avent en ligne en {land} {y}","a_title":"Calendriers de l’Avent en ligne {y} en {land} – GiveOwl","a_desc":"{n} calendriers de l’Avent en ligne en {land} pour {y} : dates, lots et comment participer.","a_all_h1":"Calendriers de l’Avent en ligne {y}","a_all_desc":"Les calendriers de l’Avent en ligne {y} dans plusieurs pays, avec les lots et les modalités de participation chez l’organisateur.","intro":"Chaque jeu renvoie au règlement officiel de l’organisateur. GiveOwl ne collecte jamais vos participations.","open":"Ouvert","ended":"Terminé","coming":"À venir","deadline":"Date limite","prize":"Lot","how":"Comment participer","enter":"Participer chez l’organisateur","app":"Rappels et liste du jour dans l’application GiveOwl : bientôt sur Google Play.","browse":"Ouvrir la liste complète avec filtres","other":"Autres pays","ended_note":"Ce jeu est terminé. Voir les jeux ouverts ({land}).","nopurchase":"Sans obligation d’achat","purchase":"Achat requis","updated":"Mis à jour le {d}","worldwide":"Monde entier","rules":"Règlement officiel","org_lang":"Le lot et les modalités sont affichés dans la langue de l’organisateur.","bycountry":"Parcourir par pays","expected":"Attendu – pas encore confirmé pour 2026","f_end_h1":"Jeux-concours qui se terminent bientôt : {land}","f_end_desc":"{n} jeux-concours ({land}) qui se terminent dans 7 jours. Dernière chance – vérifié le {d}.","f_new_h1":"Nouveaux jeux-concours cette semaine : {land}","f_new_desc":"{n} jeux-concours ({land}) ajoutés ces 7 derniers jours.","f_daily_h1":"Jeux-concours à participation quotidienne : {land}","f_daily_desc":"{n} jeux-concours ({land}) auxquels participer chaque jour.","f_lists":"Plus de listes","f_rss":"Flux RSS"}};
